            let state = match &record.state {
                types::MoveState::SourceServes => State::TmiSource,
                types::MoveState::Copying => State::TmiCopying,
                types::MoveState::Frozen => State::TmiFrozen,
                types::MoveState::Verified => State::TmiVerified,
                types::MoveState::TargetServes => State::TmiTarget,
            };
