                    let mut next = vars.clone();
                    next.source_version = next
                        .source_version
                        .checked_add(1u64)
                        .filter(|__v| *__v <= 9007199254740991u64)
                        .ok_or(overflow("tmi-write-copying"))?;
                    let emitted_2 = Emitted::TmWriteAccepted(TmWriteAcceptedPayload {});
