        type Vars = Vars;

        type Event = Event;

        type Emitted = Emitted;

        type Key = Key;

        type Record = records::RecBackupKey;

        fn initial(_key: &Key) -> (State, Vars) {
            (
                State::BkOpenI,
                Vars {
                    backup_owner: String::from("a"),
                    reads_accepted: 0u64,
                    last_read_key_owner: String::from(""),
                },
            )
        }

